script:
frappe.ui.form.on('Salary Slip', {
    employee: function(frm) {
        set_late_entry_days(frm);
    },
    start_date: function(frm) {
        set_late_entry_days(frm);
    },
    end_date: function(frm) {
        set_late_entry_days(frm);
    }
});

function set_late_entry_days(frm) {
    if (!frm.doc.employee || !frm.doc.start_date || !frm.doc.end_date) {
        return;
    }

    frappe.call({
        method: "frappe.client.get_count",
        args: {
            doctype: "Attendance",
            filters: {
                employee: frm.doc.employee,
                attendance_date: ["between", [frm.doc.start_date, frm.doc.end_date]],
                late_entry: 1,
                docstatus: 1
            }
        },
        callback: function(r) {
            frm.set_value("custom_late_entry_days", r.message || 0);
        }
    });
}

// Place this helper function at the top
function update_or_add_deduction_component(frm, component_name, amount) {
    let row_found = false;

    (frm.doc.deductions || []).forEach(row => {
        if (row.salary_component === component_name) {
            row.amount = amount;
            row_found = true;
        }
    });

    if (!row_found) {
        frm.add_child("deductions", {
            salary_component: component_name,
            amount: amount
        });
    }

    frm.refresh_field("deductions");
}

frappe.ui.form.on('Salary Slip', {
    validate: function (frm) {
        if (!frm.doc.employee || !frm.doc.start_date || !frm.doc.end_date) {
            frappe.msgprint("Please select Employee and Date Range first.");
            return;
        }

        // Step 1: Fetch employee's default shift
        frappe.call({
            method: "frappe.client.get_value",
            args: {
                doctype: "Employee",
                filters: { name: frm.doc.employee },
                fieldname: "default_shift"
            },
            callback: function (shift_res) {
                const default_shift = shift_res.message?.default_shift;

                if (!default_shift) {
                    frappe.msgprint("Default Shift not set for this employee.");
                    return;
                }

                // Step 2: Check if default shift is "General"
                if (default_shift !== "General") {
                    console.log("⛔ Not General Shift - Skipping Late Entry Calculation.");
                    update_or_add_deduction_component(frm, "Lates Entry Amount", 0); // Optionally clear
                    return;
                }

                // Step 3: Fetch base from submitted Salary Structure Assignment
                frappe.call({
                    method: "frappe.client.get_list",
                    args: {
                        doctype: "Salary Structure Assignment",
                        filters: {
                            employee: frm.doc.employee,
                            from_date: ["<=", frm.doc.end_date],
                            docstatus: 1 // Only Submitted
                        },
                        fields: ["base", "from_date"],
                        order_by: "from_date desc",
                        limit_page_length: 1
                    },
                    callback: function (r) {
                        if (!r.message || !r.message.length || !r.message[0].base) {
                            frappe.msgprint("⚠️ Submitted Salary Structure Assignment with base not found.");
                            return;
                        }

                        const base_salary = r.message[0].base;
                        const late_entries = frm.doc.custom_late_entry_days || 0;
                        const total_working_days = frm.doc.total_working_days || 0;

                        console.log("✅ Base Salary:", base_salary);
                        console.log("Late Entry Days:", late_entries);
                        console.log("Working Days:", total_working_days);

                        if (late_entries < 3 || total_working_days === 0) {
                            update_or_add_deduction_component(frm, "Lates Entry Amount", 0);
                            return;
                        }

                        const blocks = Math.floor(late_entries / 3);
                        const per_day_salary = base_salary / total_working_days;
                        const deduction = flt(per_day_salary * 0.5 * blocks, 2);

                        console.log("3-Day Blocks:", blocks);
                        console.log("Per Day Salary:", per_day_salary);
                        console.log("Late Entry Deduction:", deduction);

                        update_or_add_deduction_component(frm, "Lates Entry Amount", deduction);
                    }
                });
            }
        });
    }
});
